import { create } from "zustand";
import { persist } from "zustand/middleware";

/**
 * Representing the active dashboard service context.
 * - 'pengujian': Lab testing dashboard menu
 * - 'pelatihan': Training LMS dashboard menu
 * - null: Portal selection screen
 */
export type DashboardMode = "pengujian" | "pelatihan" | null;

interface DashboardStore {
  activeMode: DashboardMode;
  setActiveMode: (mode: DashboardMode) => void;
}

/**
 * Zustand hook to manage and persist the selected active dashboard mode context.
 */
export const useDashboardStore = create<DashboardStore>()(
  persist(
    (set) => ({
      activeMode: null, // null means show portal selection
      setActiveMode: (mode) => set({ activeMode: mode }),
    }),
    {
      name: "dashboard-active-mode-storage-v2",
    },
  ),
);
